@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2>Track Your Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number" @bind="searchTrackingNumber" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="DoTrack">Track</button>
            </div>
        </div>
    </div>

    @if (isLoading)
    {
        <p><em>Loading...</em></p>
    }
    else if (notFound)
    {
        <div class="alert alert-warning">Shipment not found. Please check the tracking number and try again.</div>
    }
    else if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">@shipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status)">@FormatStatus(shipment.Status)</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <p><strong>Origin:</strong> @shipment.Origin</p>
                        <p><strong>Destination:</strong> @shipment.Destination</p>
                        @if (!string.IsNullOrEmpty(shipment.Description))
                        {
                            <p><strong>Description:</strong> @shipment.Description</p>
                        }
                    </div>
                    <div class="col-md-6">
                        @if (shipment.EstimatedDelivery.HasValue)
                        {
                            <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                        <p><strong>Created:</strong> @shipment.CreatedAt.ToString("MMM dd, yyyy HH:mm") UTC</p>
                        @if (shipment.UpdatedAt.HasValue)
                        {
                            <p><strong>Last Updated:</strong> @shipment.UpdatedAt.Value.ToString("MMM dd, yyyy HH:mm") UTC</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private string searchTrackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool isLoading;
    private bool notFound;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchTrackingNumber = TrackingNumber;
            await LoadShipment();
        }
    }

    private async Task DoTrack()
    {
        if (!string.IsNullOrWhiteSpace(searchTrackingNumber))
        {
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(searchTrackingNumber)}");
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await DoTrack();
    }

    private async Task LoadShipment()
    {
        isLoading = true;
        notFound = false;
        shipment = null;
        try
        {
            shipment = await ShipmentService.TrackShipmentAsync(searchTrackingNumber);
            notFound = shipment is null;
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-warning text-dark",
        "InTransit" => "bg-info text-dark",
        "OutForDelivery" => "bg-primary",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out For Delivery",
        _ => status
    };
}

@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>Dispatcher Dashboard</h2>
        <button class="btn btn-success" @onclick="ToggleNewForm">
            @(showNewForm ? "Cancel" : "New Shipment")
        </button>
    </div>

    @if (showNewForm)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title">Create New Shipment</h5>
                <div class="row g-3">
                    <div class="col-md-4">
                        <label class="form-label">Tracking Number</label>
                        <input class="form-control" @bind="newShipment.TrackingNumber" placeholder="TRK-XXXXXXXX" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Origin</label>
                        <input class="form-control" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Destination</label>
                        <input class="form-control" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Customer Email</label>
                        <input class="form-control" @bind="newShipment.CustomerEmail" />
                    </div>
