    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number" @bind="searchTrackingNumber" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="DoTrack">Track</button>
            </div>
        </div>
    </div>

    @if (isLoading)
    {
        <p><em>Loading...</em></p>
    }
    else if (notFound)
    {
