+            <option value="Delivered">Delivered</option>
+            <option value="Cancelled">Cancelled</option>
+        </select>
+    </div>
+
+    @if (isLoading)
+    {
+        <p><em>Loading shipments...</em></p>
+    }
+    else
+    {
+        <div class="table-responsive">
+            <table class="table table-striped table-hover">
+                <thead class="table-dark">
+                    <tr>
+                        <th>Tracking #</th>
+                        <th>Origin</th>
+                        <th>Destination</th>
+                        <th>Status</th>
+                        <th>Est. Delivery</th>
+                        <th>Actions</th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @foreach (var s in FilteredShipments)
+                    {
+                        <tr>
+                            <td>@s.TrackingNumber</td>
+                            <td>@s.Origin</td>
+                            <td>@s.Destination</td>
+                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@FormatStatus(s.Status)</span></td>
+                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
+                            <td>
+                                @if (editingId == s.Id)
+                                {
+                                    <select class="form-select form-select-sm d-inline-block w-auto" @bind="editStatus">
+                                        <option value="Pending">Pending</option>
+                                        <option value="InTransit">In Transit</option>
+                                        <option value="OutForDelivery">Out For Delivery</option>
+                                        <option value="Delivered">Delivered</option>
+                                        <option value="Cancelled">Cancelled</option>
+                                    </select>
+                                    <button class="btn btn-sm btn-success ms-1" @onclick="() => SaveStatus(s)">Save</button>
+                                    <button class="btn btn-sm btn-secondary ms-1" @onclick="() => editingId = null">Cancel</button>
+                                }
+                                else
+                                {
+                                    <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Update Status</button>
+                                }
+                            </td>
+                        </tr>
+                    }
+                </tbody>
+            </table>
+        </div>
+    }
+</div>
+
+@code {
+    private List<ShipmentDto> shipments = [];
+    private bool isLoading = true;
+    private bool showNewForm;
+    private ShipmentDto newShipment = new() { Status = "Pending" };
+    private DateTime? estimatedDeliveryDate;
+    private string? createError;
+    private string statusFilter = string.Empty;
+    private int? editingId;
+    private string editStatus = string.Empty;
+
+    private IEnumerable<ShipmentDto> FilteredShipments =>
+        string.IsNullOrEmpty(statusFilter)
+            ? shipments
+            : shipments.Where(s => s.Status == statusFilter);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        isLoading = true;
+        try { shipments = await ShipmentService.GetShipmentsAsync(); }
+        catch { shipments = []; }
+        finally { isLoading = false; }
+    }
+
+    private void ToggleNewForm()
+    {
+        showNewForm = !showNewForm;
+        if (showNewForm)
+        {
+            newShipment = new ShipmentDto { Status = "Pending" };
+            estimatedDeliveryDate = null;
+            createError = null;
+        }
+    }
+
+    private async Task CreateShipment()
+    {
+        createError = null;
+        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) ||
+            string.IsNullOrWhiteSpace(newShipment.Origin) ||
+            string.IsNullOrWhiteSpace(newShipment.Destination))
+        {
+            createError = "Tracking number, origin, and destination are required.";
+            return;
+        }
+        if (estimatedDeliveryDate.HasValue)
+            newShipment.EstimatedDelivery = estimatedDeliveryDate.Value;
+        try
+        {
+            await ShipmentService.CreateShipmentAsync(newShipment);
+            showNewForm = false;
+            await LoadShipments();
+        }
+        catch (Exception ex)
+        {
+            createError = $"Failed to create shipment: {ex.Message}";
+        }
+    }
+
+    private void StartEdit(ShipmentDto s)
+    {
+        editingId = s.Id;
+        editStatus = s.Status;
+    }
+
+    private async Task SaveStatus(ShipmentDto s)
+    {
+        s.Status = editStatus;
+        try
+        {
+            await ShipmentService.UpdateShipmentAsync(s);
+            editingId = null;
+            await LoadShipments();
+        }
+        catch { }
+    }
+
+    private static string GetStatusBadgeClass(string status) => status switch
+    {
+        "Pending" => "bg-warning text-dark",
+        "InTransit" => "bg-info text-dark",
+        "OutForDelivery" => "bg-primary",
+        "Delivered" => "bg-success",
+        "Cancelled" => "bg-danger",
+        _ => "bg-secondary"
+    };
+
+    private static string FormatStatus(string status) => status switch
+    {
+        "InTransit" => "In Transit",
+        "OutForDelivery" => "Out For Delivery",
+        _ => status
+    };
+}
+

