using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Components;
using ShipmentTracker.Components.Account;
using ShipmentTracker.Data;
using ShipmentTracker.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents()
    .AddAuthenticationStateSerialization();

builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<IdentityRedirectManager>();
builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();

builder.Services.AddAuthentication(options =>
    {
        options.DefaultScheme = IdentityConstants.ApplicationScheme;
        options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
    })
    .AddIdentityCookies();

var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
builder.Services.AddDbContext<ApplicationDbContext>(options =>
    options.UseSqlite(connectionString));
builder.Services.AddDatabaseDeveloperPageExceptionFilter();

builder.Services.AddIdentityCore<ApplicationUser>(options =>
    {
        options.SignIn.RequireConfirmedAccount = true;
        options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
    })
    .AddRoles<IdentityRole>()
    .AddEntityFrameworkStores<ApplicationDbContext>()
    .AddSignInManager()
    .AddDefaultTokenProviders();

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

builder.Services.AddAuthorizationBuilder()
    .AddPolicy("DispatcherOnly", policy => policy.RequireRole("Dispatcher"));

builder.Services.AddScoped<IShipmentService, ServerShipmentService>();

var app = builder.Build();

// Seed roles on startup
using (var scope = app.Services.CreateScope())
{
    var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
    string[] roles = ["Dispatcher", "Customer"];
    foreach (var role in roles)
    {
        if (!await roleManager.RoleExistsAsync(role))
        {
            await roleManager.CreateAsync(new IdentityRole(role));
        }
    }
}

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseWebAssemblyDebugging();
    app.UseMigrationsEndPoint();
}
else
{
    app.UseExceptionHandler("/Error", createScopeForErrors: true);
}
app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
app.UseAntiforgery();

app.MapStaticAssets();
app.MapRazorComponents<App>()
    .AddInteractiveServerRenderMode()
    .AddInteractiveWebAssemblyRenderMode()
    .AddAdditionalAssemblies(typeof(ShipmentTracker.Client._Imports).Assembly);

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
var shipments = app.MapGroup("/api/shipments");

shipments.MapGet("/", async (ApplicationDbContext db) =>
{
    var list = await db.Shipments.ToListAsync();
    return Results.Ok(list.Select(s => new ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description,
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        UpdatedAt = s.UpdatedAt
    }));
}).RequireAuthorization();

shipments.MapGet("/my", async (ApplicationDbContext db, HttpContext httpContext) =>
{
    var email = httpContext.User.Identity?.Name;
    var list = await db.Shipments.Where(s => s.CustomerEmail == email).ToListAsync();
    return Results.Ok(list.Select(s => new ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description,
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        UpdatedAt = s.UpdatedAt
    }));
}).RequireAuthorization();

shipments.MapGet("/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    if (shipment is null) return Results.NotFound();
    return Results.Ok(new ShipmentDto
    {
        Id = shipment.Id,
        TrackingNumber = shipment.TrackingNumber,
        Origin = shipment.Origin,
        Destination = shipment.Destination,
        Status = shipment.Status,
        CustomerEmail = shipment.CustomerEmail,
        Description = shipment.Description,
        CreatedAt = shipment.CreatedAt,
        EstimatedDelivery = shipment.EstimatedDelivery,
        UpdatedAt = shipment.UpdatedAt
    });
});

shipments.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = new Shipment
    {
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = string.IsNullOrWhiteSpace(dto.Status) ? "Pending" : dto.Status,
        CustomerEmail = dto.CustomerEmail,
        Description = dto.Description,
        CreatedAt = DateTime.UtcNow,
        EstimatedDelivery = dto.EstimatedDelivery
    };
    db.Shipments.Add(shipment);
    await db.SaveChangesAsync();
    return Results.Created($"/api/shipments/{shipment.TrackingNumber}", new ShipmentDto
    {
        Id = shipment.Id,
        TrackingNumber = shipment.TrackingNumber,
        Origin = shipment.Origin,
        Destination = shipment.Destination,
        Status = shipment.Status,
        CustomerEmail = shipment.CustomerEmail,
        Description = shipment.Description,
        CreatedAt = shipment.CreatedAt,
        EstimatedDelivery = shipment.EstimatedDelivery,
        UpdatedAt = shipment.UpdatedAt
    });
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

shipments.MapPut("/{id:int}", async (int id, ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();
    shipment.Status = dto.Status;
    shipment.UpdatedAt = DateTime.UtcNow;
    await db.SaveChangesAsync();
    return Results.NoContent();
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

app.Run();

