 @page "/my-shipments"
 @using Microsoft.AspNetCore.Authorization
 @using ShipmentTracker.Client.Models
 @using ShipmentTracker.Client.Services
 @attribute [Authorize]
 @rendermode InteractiveAuto
 @inject IShipmentService ShipmentService

 <PageTitle>My Shipments</PageTitle>

 <div class="container mt-4">
     <h2>My Shipments</h2>

     @if (isLoading)
     {
         <p><em>Loading your shipments...</em></p>
     }
     else if (shipments.Count == 0)
     {
         <div class="alert alert-info">No shipments found for your account.</div>
     }
     else
     {
         <div class="row">
             @foreach (var s in shipments)
             {
                 <div class="col-md-6 col-lg-4 mb-3">
                     <div class="card h-100 shadow-sm">
                         <div class="card-body">
                             <div class="d-flex justify-content-between align-items-start mb-2">
                                 <h6 class="card-title mb-0">@s.TrackingNumber</h6>
                                 <span class="badge @GetStatusBadgeClass(s.Status)">@FormatStatus(s.Status)</span>
                             </div>
                             <p class="mb-1"><strong>Destination:</strong> @s.Destination</p>
                             @if (s.EstimatedDelivery.HasValue)
                             {
                                 <p class="mb-0 text-muted"><small>Est. Delivery: @s.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</small></p>
                             }
                         </div>
                     </div>
                 </div>
             }
         </div>
     }
 </div>

 @code {
     private List<ShipmentDto> shipments = [];
     private bool isLoading = true;

     protected override async Task OnInitializedAsync()
     {
         try { shipments = await ShipmentService.GetMyShipmentsAsync(); }
         catch { shipments = []; }
         finally { isLoading = false; }
     }

     private static string GetStatusBadgeClass(string status) => status switch
     {
         "Pending" => "bg-warning text-dark",
         "InTransit" => "bg-info text-dark",
         "OutForDelivery" => "bg-primary",
         "Delivered" => "bg-success",
         "Cancelled" => "bg-danger",
         _ => "bg-secondary"
     };

     private static string FormatStatus(string status) => status switch
     {
         "InTransit" => "In Transit",
         "OutForDelivery" => "Out For Delivery",
         _ => status
     };
 }

