1. using Microsoft.EntityFrameworkCore;
2. using ShipmentTracker.Client.Models;
3. using ShipmentTracker.Client.Services;
4. using ShipmentTracker.Data;
5. 
6. namespace ShipmentTracker.Services;
7. 
8. public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
9. {
10.     public async Task<List<ShipmentDto>> GetShipmentsAsync()
11.     {
12.         return await db.Shipments
13.             .Select(s => MapToDto(s))
14.             .ToListAsync();
15.     }
16. 
17.     public async Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber)
18.     {
19.         var shipment = await db.Shipments
20.             .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
21.         return shipment is null ? null : MapToDto(shipment);
22.     }
23. 
24.     public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
25.     {
26.         var shipment = new Shipment
27.         {
28.             TrackingNumber = dto.TrackingNumber,
29.             Origin = dto.Origin,
30.             Destination = dto.Destination,
31.             Status = dto.Status,
32.             CustomerEmail = dto.CustomerEmail,
33.             Description = dto.Description,
34.             CreatedAt = DateTime.UtcNow,
35.             EstimatedDelivery = dto.EstimatedDelivery
36.         };
37.         db.Shipments.Add(shipment);
38.         await db.SaveChangesAsync();
39.         return MapToDto(shipment);
40.     }
41. 
42.     public async Task UpdateShipmentAsync(ShipmentDto dto)
43.     {
44.         var shipment = await db.Shipments.FindAsync(dto.Id)
45.             ?? throw new InvalidOperationException("Shipment not found");
46.         shipment.Status = dto.Status;
47.         shipment.UpdatedAt = DateTime.UtcNow;
48.         await db.SaveChangesAsync();
49.     }
50. 
51.     public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
52.     {
53.         // This won't be called with proper email filtering from server-side prerender
54.         // The API endpoint handles the email filtering
55.         return await GetShipmentsAsync();
56.     }
57. 
58.     private static ShipmentDto MapToDto(Shipment s) => new()
59.     {
60.         Id = s.Id,
61.         TrackingNumber = s.TrackingNumber,
62.         Origin = s.Origin,
63.         Destination = s.Destination,
64.         Status = s.Status,
65.         CustomerEmail = s.CustomerEmail,
66.         Description = s.Description,
67.         CreatedAt = s.CreatedAt,
68.         EstimatedDelivery = s.EstimatedDelivery,
69.         UpdatedAt = s.UpdatedAt
70.     };
71. }
